"""Files CI regenerates and checks with ``git diff --exit-code`` are regenerated by the coding job."""

from __future__ import annotations

import base64
import subprocess
import tempfile
import unittest
from pathlib import Path
from unittest.mock import MagicMock

from ts_harness.implementation import generated_artifacts as ga

CI = """
name: ci
on: pull_request
jobs:
  checks:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: npm ci
      - run: npm test
      - name: openapi is current
        run: |
          npm run openapi
          git diff --exit-code openapi.json || (echo "::error::openapi.json is out of date" && exit 1)
      - run: npx prisma generate
      - run: git diff --quiet -- src/generated/client.ts
      - run: npm run deploy:docs
      - run: git diff --exit-code docs/
"""


def _repo(root: Path, ci: str = CI) -> Path:
    workflows = root / ".github" / "workflows"
    workflows.mkdir(parents=True)
    (workflows / "ci.yml").write_text(ci, encoding="utf-8")
    return root


class GeneratorStepTests(unittest.TestCase):
    def test_finds_the_generators_ci_checks_and_skips_unsafe_commands(self):
        with tempfile.TemporaryDirectory() as tmp:
            steps = ga.generator_steps(_repo(Path(tmp)))
        self.assertEqual([(s.command, s.files) for s in steps], [
            ("npm run openapi", ["openapi.json"]),
            ("npx prisma generate", ["src/generated/client.ts"]),
        ])  # "npm run deploy:docs" is never run

    def test_no_workflows_no_generators(self):
        with tempfile.TemporaryDirectory() as tmp:
            self.assertEqual(ga.generator_steps(Path(tmp)), [])

    def test_regenerate_reports_what_changed(self):
        calls = []

        def runner(cmd, **kwargs):
            calls.append(cmd)
            if cmd[:2] == ["git", "status"]:
                return subprocess.CompletedProcess(cmd, 0, stdout=" M openapi.json\n" if "openapi.json" in cmd else "", stderr="")
            return subprocess.CompletedProcess(cmd, 0, stdout="wrote openapi.json", stderr="")

        with tempfile.TemporaryDirectory() as tmp:
            results = ga.regenerate(_repo(Path(tmp)), runner=runner)
        self.assertEqual(results[0]["command"], "npm run openapi")
        self.assertEqual(results[0]["changed"], ["openapi.json"])
        self.assertEqual(results[1]["changed"], [])
        self.assertIn(["sh", "-c", "npm run openapi"], calls)

    def test_generated_files_read_from_github(self):
        github = MagicMock()
        files = {".github/workflows": [{"name": "ci.yml", "path": ".github/workflows/ci.yml"}],
                 ".github/workflows/ci.yml": {"content": base64.b64encode(CI.encode()).decode()}}
        github.get_file.side_effect = lambda owner, repo, path, ref: files.get(path)
        self.assertEqual(ga.generated_files_on_github(github, "o", "r", "sha"), {"openapi.json", "src/generated/client.ts"})


class VerificationTests(unittest.TestCase):
    def _verify(self, generator_rc: int):
        from ts_harness.implementation.verification import verify_implementation

        def runner(cmd, **kwargs):
            if cmd[:2] == ["git", "status"]:
                return subprocess.CompletedProcess(cmd, 0, stdout=" M openapi.json\n" if "openapi.json" in cmd else "", stderr="")
            if cmd[:2] == ["sh", "-c"] and cmd[2] == "npm run openapi":
                return subprocess.CompletedProcess(cmd, generator_rc, stdout="", stderr="boom" if generator_rc else "")
            return subprocess.CompletedProcess(cmd, 0, stdout="", stderr="")

        with tempfile.TemporaryDirectory() as tmp:
            repo = _repo(Path(tmp), CI.split("      - run: npx prisma generate")[0])
            return verify_implementation(repo, work_order_body="chore: x", work_order_id="WO-1", changed_files=["src/x.ts"], runner=runner)

    def test_a_regenerated_file_is_noted_and_a_failing_generator_fails_verification(self):
        ok = self._verify(0)
        self.assertNotIn("generated_files_failed", ok.reasons)
        self.assertTrue(any("regenerated openapi.json (npm run openapi)" in w for w in ok.warnings))
        self.assertEqual(next(c for c in ok.checks if c["check"] == "generate")["changed"], ["openapi.json"])
        failed = self._verify(1)
        self.assertIn("generated_files_failed", failed.reasons)


class ScopeTests(unittest.TestCase):
    def test_a_regenerated_file_is_not_out_of_scope(self):
        from ts_harness.workflows.code_review import scope_findings

        body = "## Files\n- src/x.ts\n"
        files = [{"filename": "src/x.ts"}, {"filename": "openapi.json"}]
        self.assertEqual([f["file"] for f in scope_findings("pr", files, body)], ["openapi.json"])
        self.assertEqual(scope_findings("pr", files, body, {"openapi.json"}), [])


if __name__ == "__main__":
    unittest.main()
